/** Anyone or anything a business deals with as one, whether a person or an organization */
export interface PartyRow {
  /** What identifies the party, made by the application when the party is created */
  readonly partyId: string;
  /** Whether the party is a person or an organization */
  readonly partyKindCode: string;
  /** The name the party is shown by, whatever its parts are */
  readonly displayName: string;
}

/** What an insert into party takes: what the database fills may be left out. */
export interface PartyInsert {
  readonly partyId: string;
  readonly partyKindCode: string;
  readonly displayName: string;
}

