export type PartyKey = { readonly partyId: string };

/** Anyone or anything a business deals with as one, whether a person or an organization */
export const party = defineTable<PartyRow, PartyInsert, "party">({
  alias: "party",
  name: "party",
  columns: {
    partyId: "party_id",
    partyKindCode: "party_kind_code",
    displayName: "display_name",
  },
  primaryKey: ["partyId"],
  foreignKeys: [
    { columns: ["partyKindCode"], references: "partyKind", referencesColumns: ["code"] },
  ],
});

